// HasIntent applies the HasEdge predicate on the "intent" edge.
func HasIntent() predicate.WalletSweep {
	return predicate.WalletSweep(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, IntentTable, IntentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasIntentWith applies the HasEdge predicate on the "intent" edge with a given conditions (other predicates).
func HasIntentWith(preds ...predicate.OnchainPaymentIntent) predicate.WalletSweep {
	return predicate.WalletSweep(func(s *sql.Selector) {
		step := newIntentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WalletSweep) predicate.WalletSweep {
	return predicate.WalletSweep(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WalletSweep) predicate.WalletSweep {
	return predicate.WalletSweep(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WalletSweep) predicate.WalletSweep {
	return predicate.WalletSweep(sql.NotPredicates(p))
}
